        assertTrue(governanceEmail.body().contains("Saída: 22/03/2027"));

        assertTrue(financeEmail.body().contains("Valor: R$ "));
    }

    @Test
    void anUnknownReservationIsNotFound() {
        assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
    }
}

